package com.ethk3.novaonepro.strategyv2;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import com.ethk3.novaonepro.*;
import java.nio.file.*;
import java.util.*;

/** Actual fenced legacy warm-bootstrap SQL/files, including an unserved second expiry. */
public final class LegacyWarm {
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static long value(SQLiteDatabase db,String sql){try(Cursor c=db.rawQuery(sql,null)){check(c.moveToFirst(),"Missing scalar");return c.getLong(0);}}
    static StageStrategySU2.Definition stage(String text,long through){int columns=StageLayerSU2.BASE_COLS+1;double[][] variance=new double[1][columns];Arrays.fill(variance[0],1);double[] sd=new double[columns];Arrays.fill(sd,1);double[] seed=new double[100];Arrays.fill(seed,.3);StageLayerSU2.Layer layer=new StageLayerSU2.Layer(new StageLayerSU2.Gmm(new double[1][columns],variance,new double[]{1},0),new double[columns],sd,new double[1][4],new double[]{1});return new StageStrategySU2.Definition("F30",.3,through,Collections.singletonList(text),layer,seed);}
    public static void main(String[] args)throws Exception{
        Path directory=Files.createTempDirectory("r26-legacy-warm-");
        try(SQLiteDatabase db=new SQLiteDatabase(args[0])){
            db.beginTransaction();try{RuntimeSchemaR26.ensure(db);db.setTransactionSuccessful();}finally{db.endTransaction();}db.execSQL("CREATE TABLE draws(issue TEXT PRIMARY KEY,dirty INTEGER NOT NULL)");
            long first=TargetIssueResolver.sequenceOrdinalSU1("202610220001"),now=System.currentTimeMillis();List<Models.Draw> draws=new ArrayList<>();WarmBirth.append(draws,db,first,0);DbStore store=new DbStore(db,new android.content.Context(directory.toFile()),draws);RuntimeCoordinatorR26.Claim claim=new RuntimeCoordinatorR26.Claim("legacy-test","SYNTHETIC",1,0);BudgetTokenSU1 budget=new BudgetTokenSU1(30000,100000000,()->false);
            db.execSQL("INSERT INTO r26_session VALUES('SYNTHETIC',1,'SYNTHETIC','RUNNING',?,0)",new Object[]{now});db.execSQL("INSERT INTO r26_task(task_id,lane,mechanism,fence,lease_until,owner,status) VALUES('legacy-test','P2','test',1,?,'SYNTHETIC','RUNNING')",new Object[]{now+600000});
            FoundryCampaignR26.Snapshot source=FoundryCampaignR26.capture(store);String sourceHash=LiveStateR26.hash(source.encode());ModelGenomeSU2 a=FamilyRegistryR26.genome("F20").bindBirth(sourceHash,source.through),b=FamilyRegistryR26.genome("F19").bindBirth(sourceHash,source.through);StageStrategySU2.Definition stage=stage(a.text(),source.through);StageStrategySU2.register(stage);List<String> canonical=Arrays.asList(a.text(),new CommitteeSU2(Arrays.asList(a,b),.3).text(),stage.text());LegacyReplayStateR26 learned=new LegacyReplayStateR26(canonical,first);for(int i=0;i<37;i++)learned.advance(source.draws[i],source.ordinal[i]);String roster=HashingSU1.fields("R26_LEGACY_ROSTER_V1",ResearchSemanticsGeneratedR967.TRAINING_RULE_SHA256,PolicyIdentityR26.canonical(canonical));CheckpointArtifactsR26 files=CheckpointArtifactsR26.forStore(store);String parent;byte[] expiredReference;
            try(CheckpointArtifactsR26.Prepared file=files.prepareLegacy(learned)){
                expiredReference=file.reference();String hash=LiveStateR26.hash(files.resolve(file.reference()));parent=HashingSU1.fields("R26_LEGACY_CHECKPOINT_V1",roster,sourceHash,"0",hash);db.beginTransaction();try{db.execSQL("INSERT INTO r26_legacy_runtime(singleton,roster_hash,snapshot_hash,snapshot,source_through,genesis_ordinal,through_ordinal,cursor,state,state_hash,checkpoint_hash,parent_hash,numerical_abi,status,updated_at) VALUES(1,?,?,X'',?,?,?,?,?,?,?,'',?,'EXPIRED_RETENTION',1)",new Object[]{roster,sourceHash,source.through,first,learned.through(),37,file.reference(),hash,parent,ResearchSemanticsGeneratedR967.TRAINING_RULE_SHA256});CheckpointManifestR26.record(db,parent,"LEGACY:"+roster,sourceHash,"",learned.through(),file.reference());db.setTransactionSuccessful();}finally{db.endTransaction();}
            }
            learned.onGap();
            check(LegacyReplayR26.resumeExpired(store,()->claim,budget)==0,"Exposed source was reused without later labels");check(value(db,"SELECT count(*) FROM r26_legacy_runtime WHERE status='EXPIRED_RETENTION'")==1,"Waiting destroyed the parent");
            for(int window=1;window<=2;window++){
                WarmBirth.append(draws,db,first,window*6000);if(window==1){try{LegacyReplayR26.resumeExpired(store,()->new RuntimeCoordinatorR26.Claim("legacy-test","SYNTHETIC",0,0),budget);throw new AssertionError("Stale fence transferred parent");}catch(IllegalStateException expected){}}
                check(LegacyReplayR26.resumeExpired(store,()->claim,budget)==1,"Warm bootstrap failed");
                try(Cursor row=db.rawQuery("SELECT snapshot,state,state_hash,checkpoint_hash,parent_hash,cursor FROM r26_legacy_runtime",null)){check(row.moveToFirst(),"Missing resumed row");FoundryCampaignR26.Snapshot suffix=FoundryCampaignR26.Snapshot.decode(row.getBlob(0));check(suffix.ordinal[0]==first+window*6000&&suffix.draws.length==128,"Old exposure leaked into suffix");LegacyReplayStateR26 restored=files.restoreLegacy(row.getBlob(1),row.getString(2));check(Arrays.equals(learned.encode(),restored.encode())&&restored.samples()==37,"Program/committee/stage state or lifetime reset");check(parent.equals(row.getString(4))&&row.getInt(5)==0,"Parent chain/source clock");parent=row.getString(3);LegacyReplayStateR26 reference=LegacyReplayStateR26.decode(learned.encode());restored.advance(suffix.draws[0],suffix.ordinal[0]);reference.advance(suffix.draws[0],suffix.ordinal[0]);check(Arrays.equals(reference.encode(),restored.encode())&&restored.samples()==38,"Subsequent actual update differs");}
                check(value(db,"SELECT count(*) FROM r26_cohort")==0&&value(db,"SELECT count(*) FROM r26_live_model")==0,"Warm bootstrap created authority");check(value(db,"SELECT count(*) FROM r26_checkpoint_artifact")==window+1,"Manifest chain");if(window==1)db.execSQL("UPDATE r26_legacy_runtime SET status='EXPIRED_RETENTION',snapshot=X''");
            }
            check(!CheckpointReferencesR26.hashes(db).contains(CheckpointArtifactsR26.referenceHash(expiredReference)),"Expired legacy parent raw context stayed pinned");files.prune(()->CheckpointReferencesR26.hashes(db),System.currentTimeMillis()+120000,0,256);try{CheckpointArtifactsR26.resolve(store,expiredReference);throw new AssertionError("Expired legacy raw file retained");}catch(java.io.IOException expected){}
            byte[] preserved;try(Cursor c=db.rawQuery("SELECT state FROM r26_legacy_runtime",null)){check(c.moveToFirst(),"Missing state");preserved=c.getBlob(0);}db.execSQL("UPDATE r26_legacy_runtime SET status='EXPIRED_RETENTION',state_hash='DAMAGED'");check(LegacyReplayR26.resumeExpired(store,()->claim,budget)==0,"Corrupt binding was executed");check(value(db,"SELECT count(*) FROM r26_legacy_runtime WHERE status='BLOCKED_WARM_STATE_PRESERVED'")==1,"Corrupt parent not quarantined");try(Cursor c=db.rawQuery("SELECT state FROM r26_legacy_runtime",null)){check(c.moveToFirst()&&Arrays.equals(preserved,c.getBlob(0)),"Quarantine discarded bytes");}
            db.execSQL("UPDATE r26_legacy_runtime SET status='EXPIRED_RETENTION',numerical_abi='OLD'");check(LegacyReplayR26.resumeExpired(store,()->claim,budget)==0,"Old numerical ABI executed");check(value(db,"SELECT count(*) FROM r26_legacy_runtime WHERE status='BLOCKED_NUMERICAL_ABI_PRESERVED'")==1,"Old ABI not preserved");
            System.out.println("R26_LEGACY_WARM_PASS|programCommitteeStage=true|allLearnedStateAndLifetimePreserved=true|strictLaterExposure=true|twoExpiriesIncludingUnserved=true|staleFenceRejected=true|checkpointParentCas=true|nextUpdateExact=true|expiredParentRawStateUnpinnedAndPruned=true|corruptAndOldAbiPreserved=true|noQualification=true|scope=HOST_PRODUCTION_SQLITE_FILES_WITH_ANDROID_TRANSPORT_ADAPTERS");
        }finally{try(java.util.stream.Stream<Path> paths=Files.walk(directory)){for(Path p:(Iterable<Path>)paths.sorted(Comparator.reverseOrder())::iterator)Files.delete(p);}}
    }
}
